definition.script:
pipeline {
    agent any
    parameters{
        choice(
            name: '选择', 
            choices: ['ruoyi1', 'Run'], 
            description: 'ruoyi1 运行 open_ruoyi3.py，Run 运行 open_ruoyi4.py'
        )
    }
    stages {
        stage('Run') {
            when { expression { params.选择 == 'Run' } }  // 关键条件
            steps {
                bat 'C:\\Users\\31276\\AppData\\Local\\Programs\\Python\\Python38\\python.exe D:\\Git\\RuoYi\\ruoyi-test\\pythonProject2\\RuoYi\\open_ruoyi4.py'
            }
        }
        stage('ruoyi1') {
            when { expression { params.选择 == 'ruoyi1' } }  // 关键条件
            steps {
                bat 'C:\\Users\\31276\\AppData\\Local\\Programs\\Python\\Python38\\python.exe D:\\Git\\RuoYi\\ruoyi-test\\pythonProject2\\RuoYi\\open_ruoyi3.py'
            }
        }
    }
}
